/// One applicable policy in the loop of rules.rs authorize: no condition grants; a condition grants when it evaluates to Bool(true); Null fails the check as "is null", any other value as "is false", an evaluation error as failed.
///
/// Specification function `policy-step`.
pub fn policy_step(
    policy: &types::PolicyDef,
    env: &types::ExprEnv,
    acc: &types::PolicyProgress,
    what: &String,
) -> types::PolicyProgress {
    let rule = format!("policy:{}", policy.id.0);
    match &policy.condition {
        None => types::PolicyProgress {
            granted: Some(types::PolicyCheck {
                rule: rule.clone(),
                passed: true,
                what: what.clone(),
                outcome: types::PolicyOutcome::Unconditional,
                condition: None,
            }),
            checks: acc.checks.clone(),
        },
        Some(c) => match support::eval_tenant_rule_language_expr_env(c, env) {
            Ok(v) => match &v {
                types::Value::Bool(b) => {
                    if *b {
                        types::PolicyProgress {
                            granted: Some(types::PolicyCheck {
                                rule: rule.clone(),
                                passed: true,
                                what: what.clone(),
                                outcome: types::PolicyOutcome::Held,
                                condition: Some(c.clone()),
                            }),
                            checks: acc.checks.clone(),
                        }
                    } else {
                        deny(acc, &rule, what, &types::PolicyOutcome::IsFalse, c)
                    }
                }
                types::Value::Int(_) => deny(acc, &rule, what, &types::PolicyOutcome::IsFalse, c),
                types::Value::Str(_) => deny(acc, &rule, what, &types::PolicyOutcome::IsFalse, c),
                types::Value::Time(_) => deny(acc, &rule, what, &types::PolicyOutcome::IsFalse, c),
                types::Value::Ref(_) => deny(acc, &rule, what, &types::PolicyOutcome::IsFalse, c),
                types::Value::List(_) => deny(acc, &rule, what, &types::PolicyOutcome::IsFalse, c),
                _ => deny(acc, &rule, what, &types::PolicyOutcome::IsNull, c),
            },
            Err(_) => deny(acc, &rule, what, &types::PolicyOutcome::Failed, c),
        },
    }
}

/// crates/kernel/src/rules.rs authorize with no lookup: default deny; the owner role is allowed everything (policy:builtin_owner); a permission of one of the principal's roles (effective-permissions) on the object type and for the verb of the action grants, before any policy (permission:role, whose detail is the request, as an unconditional policy's is); otherwise the policies of the schema, in id order, that match role, action and resource are tried: the first without a condition, or whose condition evaluates to true, grants alone; a condition that is false, null or fails to evaluate is a failed check policy:<id>; with no matching policy the one check is policy:none. Without a lookup a condition that follows a reference (through) fails to evaluate, as in the kernel.
///
/// Specification function `authorize`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn authorize(
    tenant: &types::TenantState,
    schema: &types::TenantSchema,
    principal: &types::Principal,
    now: crate::prelude::Timestamp,
    action: &types::Action,
    resource: &types::Resource,
    subject: &types::Subject,
) -> Result<types::PolicyDecision, Fault> {
    let roles = roles_of(tenant, principal);
    let what = request_text(action, resource);
    Ok(if roles.iter().any(|r| r.0 == "owner") {
        types::PolicyDecision {
            allowed: true,
            checks: vec![types::PolicyCheck {
                rule: "policy:builtin_owner".to_string(),
                passed: true,
                what: what.clone(),
                outcome: types::PolicyOutcome::Owner,
                condition: None,
            }],
        }
    } else if match resource {
        types::Resource::Object(_) => effective_permissions(tenant, principal)
            .iter()
            .any(|g| grant_allows(g, action, resource)),
        _ => false,
    } {
        types::PolicyDecision {
            allowed: true,
            checks: vec![types::PolicyCheck {
                rule: "permission:role".to_string(),
                passed: true,
                what: what.clone(),
                outcome: types::PolicyOutcome::Unconditional,
                condition: None,
            }],
        }
    } else {
        {
            let env = types::ExprEnv {
                record: scope_of(
                    &(if subject.old.is_none() {
                        subject.new.clone()
                    } else {
                        subject.old.clone()
                    }),
                )?,
                old: scope_of(&subject.old)?,
                new: scope_of(&subject.new)?,
                param: std::collections::BTreeMap::<String, types::Value>::new(),
                now: types::Value::Time(now.0),
                principal: match principal {
                    types::Principal::User(id) => types::Value::Str(id.clone().0),
                    _ => null_value(),
                },
                has_role: roles
                    .clone()
                    .into_iter()
                    .map(|item_| item_.0)
                    .collect::<Vec<_>>(),
            };
            {
                let state = schema.policies.values().fold(
                    types::PolicyProgress {
                        granted: None,
                        checks: Vec::<types::PolicyCheck>::new(),
                    },
                    |acc, p| {
                        if acc.granted.is_some() || !policy_applies(p, &roles, action, resource) {
                            acc.clone()
                        } else {
                            policy_step(p, &env, &acc, &what)
                        }
                    },
                );
                match &state.granted {
                    Some(c) => types::PolicyDecision {
                        allowed: true,
                        checks: vec![c.clone()],
                    },
                    None => types::PolicyDecision {
                        allowed: false,
                        checks: if state.checks.is_empty() {
                            vec![types::PolicyCheck {
                                rule: "policy:none".to_string(),
                                passed: false,
                                what: what.clone(),
                                outcome: types::PolicyOutcome::NoPolicy,
                                condition: None,
                            }]
                        } else {
                            state.checks.clone()
                        },
                    },
                }
            }
        }
    })
}

/// crates/kernel/src/read.rs visible, the pure body of contract check-record-visibility (CT-005): whether a principal may read a stored record, the decision read makes per row: authorize Read on the record's object type, against the tenant's own schema, with the record as old and new and no lookup.
///
/// Specification function `visible`; an integer overflow, a division by zero or a failed conversion is a `Fault`.
pub fn visible(
    tenant: &types::TenantState,
    principal: &types::Principal,
    record: &types::Record,
    now: crate::prelude::Timestamp,
) -> Result<bool, Fault> {
    Ok(authorize(
        tenant,
        std::sync::Arc::as_ref(&tenant.schema),
        principal,
        now,
        &types::Action::Read,
        &types::Resource::Object(record.object.clone()),
        &types::Subject {
            old: Some(record.clone()),
            new: Some(record.clone()),
        },
    )?
    .allowed)
}

