/// value.rs FieldType::admits for a type that is not a list. A list type here is an element type of a list of lists, which schema problems refuse; it admits nothing.
///
/// Specification function `scalar-admits`.
pub fn scalar_admits(ty: &types::FieldType, x: &types::Value) -> bool {
    match ty {
        types::FieldType::Str => match x {
            types::Value::Str(_) => true,
            _ => false,
        },
        types::FieldType::Int => match x {
            types::Value::Int(_) => true,
            _ => false,
        },
        types::FieldType::Bool => match x {
            types::Value::Bool(_) => true,
            _ => false,
        },
        types::FieldType::Time => match x {
            types::Value::Time(_) => true,
            _ => false,
        },
        types::FieldType::Ref { .. } => match x {
            types::Value::Ref(_) => true,
            _ => false,
        },
        types::FieldType::List(_) => false,
        types::FieldType::File { .. } => match x {
            types::Value::Str(_) => true,
            _ => false,
        },
        types::FieldType::Language => match x {
            types::Value::Str(_) => true,
            _ => false,
        },
    }
}

/// value.rs FieldType::admits: whether a non-null value has the type; a list admits a list whose items all have its element type.
///
/// Specification function `field-type-admits`.
pub fn field_type_admits(ty: &types::FieldType, x: &types::Value) -> bool {
    match ty {
        types::FieldType::List(inner) => match x {
            types::Value::List(items) => items.iter().all(|i| scalar_admits(&(**inner), i)),
            _ => false,
        },
        _ => scalar_admits(ty, x),
    }
}

