/// definitions.rs check_expr without truth: the problem of an expression of a definition at a place, named what, that does not check.
///
/// Specification function `expr-problem`.
pub fn expr_problem(
    at: &String,
    what: &String,
    e: &types::Expr,
    env: &types::ExprCheckEnv,
) -> Vec<String> {
    match support::check_tenant_rule_language_expr_check_env(e, env) {
        Ok(_) => Vec::<String>::new(),
        Err(err) => vec![format!("{at}: {what}: {err}")],
    }
}

/// definitions.rs check_expr with truth: the problem of a condition of a definition that does not check, or checks as a shape other than bool or any.
///
/// Specification function `truth-problem`.
pub fn truth_problem(
    at: &String,
    what: &String,
    e: &types::Expr,
    env: &types::ExprCheckEnv,
) -> Vec<String> {
    match support::check_tenant_rule_language_expr_check_env(e, env) {
        Ok(s) => {
            if s == "bool" || s == "any" {
                Vec::<String>::new()
            } else {
                vec![format!(
                    "{at}: {what} is {}, not a truth value",
                    shape_debug(&s)
                )]
            }
        }
        Err(err) => vec![format!("{at}: {what}: {err}")],
    }
}

/// definitions.rs is_param_name: whether a name can be read as param.<name>: [a-z][a-z0-9_]*.
///
/// Specification function `is-param-name`.
pub fn is_param_name(name: &String) -> bool {
    let cs = name.as_str().chars().map(String::from).collect::<Vec<_>>();
    match cs.get(0) {
        Some(c0) => {
            support::every_char(c0.as_str(), char::is_ascii_lowercase)
                && cs.iter().all(|c| {
                    support::every_char(c.as_str(), char::is_ascii_lowercase)
                        || support::every_char(c.as_str(), char::is_ascii_digit)
                        || *c == "_"
                })
        }
        None => false,
    }
}

/// definitions.rs repeated: the names that occur more than once, each once, in the order of their first occurrence.
///
/// Specification function `repeated-names`.
pub fn repeated_names(names: &Vec<String>) -> Vec<String> {
    let distinct = names.iter().fold(Vec::<String>::new(), |acc, n| {
        if acc.iter().any(|a| *a == *n) {
            acc.clone()
        } else {
            support::concat(&acc, &[n.clone()])
        }
    });
    distinct
        .iter()
        .filter(|&n| {
            u64::try_from(
                names
                    .iter()
                    .filter(|&m| *m == *n)
                    .cloned()
                    .collect::<Vec<_>>()
                    .len(),
            )
            .unwrap_or(u64::MAX)
                > 1
        })
        .cloned()
        .collect::<Vec<_>>()
}

/// definitions.rs unique_problems (D-6558, CMS-1556): per composite unique constraint of an object type, in id order: a count of fields other than two to four, each field that the type does not declare or that is a list field (in the order named), a field named twice, and a blank message.
///
/// Specification function `unique-problems`.
pub fn unique_problems(object: &types::ObjectTypeDef) -> Vec<String> {
    uniques_of(object)
        .values()
        .fold(
            Vec::<String>::new(),
            |ps, u| {
                let at = format!("{}.{}", object.id.0, u.id.0);
                {
                    let n = u64::try_from(u.fields.len()).unwrap_or(u64::MAX);
                    support::concat(
                        &support::concat(
                            &support::concat(
                                &support::concat(
                                    &ps,
                                    &(if n < 2 || n > 4 {
                                        vec![
                                            format!("{at}: a unique constraint names {n} fields, not two to four")
                                        ]
                                    } else {
                                        Vec::<String>::new()
                                    }),
                                ),
                                &u
                                    .fields
                                    .iter()
                                    .fold(
                                        Vec::<String>::new(),
                                        |qs, f| support::concat(
                                            &qs,
                                            &(match object.fields.get(f) {
                                                None => vec![format!("{at}: unknown field {}", f.0)],
                                                Some(d) => {
                                                    match &d.ty {
                                                        types::FieldType::List(_) => {
                                                            vec![format!("{at}: {} is a list field", f.0)]
                                                        }
                                                        _ => Vec::<String>::new(),
                                                    }
                                                }
                                            }),
                                        ),
                                    ),
                            ),
                            &(if u64::try_from(
                                    u
                                        .fields
                                        .iter()
                                        .fold(
                                            Vec::<types::FieldId>::new(),
                                            |acc, f| {
                                                if acc.iter().any(|a| *a == *f) {
                                                    acc.clone()
                                                } else {
                                                    support::concat(&acc, &[f.clone()])
                                                }
                                            },
                                        )
                                        .len(),
                                )
                                .unwrap_or(u64::MAX) < n
                            {
                                vec![format!("{at}: names a field twice")]
                            } else {
                                Vec::<String>::new()
                            }),
                        ),
                        &(if u.message.as_str().trim().to_string() == "" {
                            vec![format!("{at}: a unique constraint needs a message")]
                        } else {
                            Vec::<String>::new()
                        }),
                    )
                }
            },
        )
}

/// rules.rs Lookup::by_fields (D-6558): the records of an object type whose every named field equals its value, in id order; refused when the snapshot does not cover the question (one by-fields need, CMS-1557).
///
/// Specification function `lookup-by-fields`; fails with `rejection`.
pub fn lookup_by_fields(
    tenant: &types::TenantState,
    coverage: &types::Coverage,
    object: &types::ObjectTypeId,
    wanted_fields: &std::collections::BTreeMap<types::FieldId, types::Value>,
) -> Result<Vec<types::Record>, types::Rejection> {
    let wanted = types::Need::ByFields {
        object: object.clone(),
        fields: wanted_fields.clone(),
    };
    Ok((if covers(coverage, &wanted) {
        match tenant.records.get(object) {
            Some(rs) => rs
                .values()
                .filter(|&r| {
                    wanted_fields
                        .keys()
                        .all(|k| r.fields.get(k) == wanted_fields.get(k))
                })
                .cloned()
                .collect::<Vec<_>>(),
            None => Vec::<std::sync::Arc<types::Record>>::new(),
        }
    } else {
        return Err(types::Rejection::Rejected(insufficient(&wanted)));
    })
    .into_iter()
    .map(|item_| <types::Record as Clone>::clone(&item_))
    .collect::<Vec<_>>())
}

/// rules.rs validate_record, one composite unique constraint (CMS-1554, CMS-1555): nothing when a field of it has no value; otherwise one lookup of the records with the same values (lookup-by-fields), and a clash with another record fails unique:<object>.<constraint> as UniqueViolated, naming the other record only when the principal may read it.
///
/// Specification function `unique-step`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn unique_step(
    tenant: &types::TenantState,
    coverage: &types::Coverage,
    object: &types::ObjectTypeDef,
    candidate: &types::Record,
    principal: &types::Principal,
    now: crate::prelude::Timestamp,
    acc: &types::ValidationOutcome,
    u: &types::UniqueDef,
) -> Result<types::ValidationOutcome, Failure<types::Rejection>> {
    let wanted = u.fields.iter().fold(
        std::collections::BTreeMap::<types::FieldId, types::Value>::new(),
        |m, f| match candidate.fields.get(f) {
            Some(x) => {
                if value_is_null(x) {
                    m.clone()
                } else {
                    {
                        let mut map_ = m.clone();
                        map_.insert(f.clone(), x.clone());
                        map_
                    }
                }
            }
            None => m.clone(),
        },
    );
    let rule = format!("unique:{}.{}", object.id.0, u.id.0);
    Ok(
        if u64::try_from(wanted.keys().cloned().collect::<Vec<_>>().len()).unwrap_or(u64::MAX)
            != u64::try_from(u.fields.len()).unwrap_or(u64::MAX)
        {
            acc.clone()
        } else {
            match lookup_by_fields(tenant, coverage, &object.id, &wanted)
                .map_err(Failure::Error)?
                .iter()
                .find(|&o| o.id.clone().0 != candidate.id.clone().0)
            {
                Some(o) => {
                    if visible(tenant, principal, o, now).map_err(Failure::Fault)? {
                        outcome_fail(
                            acc,
                            &types::ErrorKind::UniqueViolated,
                            &rule,
                            &format!("{}: record {} already has these values", u.message, o.id.0),
                        )
                    } else {
                        outcome_fail(
                            acc,
                            &types::ErrorKind::UniqueViolated,
                            &rule,
                            &format!("{}: another record already has these values", u.message),
                        )
                    }
                }
                None => outcome_pass(acc, &rule, &"no other record has these values".to_string()),
            }
        },
    )
}

/// transition.rs duplicate_pair (CMS-1556): over the records of an object type in id order, the first record whose values in every field of a composite unique constraint, none of them null, equal those of an earlier record, as the failed check unique:<object>.<constraint> naming the earlier and the later record; none when there is no such pair.
///
/// Specification function `duplicate-check`.
pub fn duplicate_check(
    records: &Vec<types::Record>,
    object: &types::ObjectTypeId,
    u: &types::UniqueDef,
) -> Vec<types::Check> {
    let keyed = records
        .iter()
        .filter(|&r| {
            u.fields.iter().all(|f| match r.fields.get(f) {
                Some(x) => !value_is_null(x),
                None => false,
            })
        })
        .cloned()
        .collect::<Vec<_>>();
    let names = u.fields.iter().fold("".to_string(), |acc, f| {
        if acc == "" {
            format!("{}", f.0)
        } else {
            format!("{acc}, {}", f.0)
        }
    });
    let found = keyed.iter().fold(Vec::<String>::new(), |acc, r| {
        if !acc.is_empty() {
            acc.clone()
        } else {
            match keyed.iter().find(|&e| {
                e.id.clone().0 < r.id.clone().0
                    && u.fields.iter().all(|f| e.fields.get(f) == r.fields.get(f))
            }) {
                Some(e) => {
                    vec![format!(
                        "records {} and {} have the same values in {names}",
                        e.id.0, r.id.0
                    )]
                }
                None => Vec::<String>::new(),
            }
        }
    });
    found
        .iter()
        .map(|detail| types::Check {
            rule: format!("unique:{}.{}", object.0, u.id.0),
            passed: false,
            detail: detail.clone(),
        })
        .collect::<Vec<_>>()
}

/// transition.rs plan_migration, the check of CMS-1556: for each define-unique change, in order, on an object type the current schema already has, the constraint as the working copy holds it is checked against the records of the type (duplicate-check); the first pair found, as a failed check, or none.
///
/// Specification function `unique-duplicates`; fails with `rejection`.
pub fn unique_duplicates(
    tenant: &types::TenantState,
    coverage: &types::Coverage,
    current: &types::TenantSchema,
    schema: &types::TenantSchema,
    changes: &Vec<types::SchemaChange>,
) -> Result<Vec<types::Check>, types::Rejection> {
    Ok({
        let mut found: Vec<types::Check> = Vec::<types::Check>::new();
        for c in changes.iter() {
            found = if !found.is_empty() {
                found.clone()
            } else {
                match c {
                    types::SchemaChange::DefineUnique { object, unique } => {
                        if current.objects.get(object).is_none() {
                            found.clone()
                        } else {
                            match schema.objects.get(object) {
                                Some(o) => match uniques_of(o).get(&unique.id) {
                                    Some(u) => duplicate_check(
                                        &lookup_all(tenant, coverage, object)?,
                                        object,
                                        u,
                                    ),
                                    None => found.clone(),
                                },
                                None => found.clone(),
                            }
                        }
                    }
                    _ => found.clone(),
                }
            };
        }
        found
    })
}

/// definitions.rs event_params (D-6523): the parameters an event of a kind binds for a trigger condition: seq, at and hop, and those of its kind.
///
/// Specification function `event-params`.
pub fn event_params(event: &types::TriggerEvent) -> Vec<String> {
    support::concat(
        &["seq".to_string(), "at".to_string(), "hop".to_string()],
        &(match event {
            types::TriggerEvent::RecordCreated { .. } => Vec::<String>::new(),
            types::TriggerEvent::RecordUpdated { .. } => vec!["transition".to_string()],
            types::TriggerEvent::RecordDeleted { .. } => Vec::<String>::new(),
            types::TriggerEvent::SegmentEntered { .. } => {
                vec![
                    "person".to_string(),
                    "segment".to_string(),
                    "reason".to_string(),
                ]
            }
            types::TriggerEvent::SegmentExited { .. } => {
                vec![
                    "person".to_string(),
                    "segment".to_string(),
                    "reason".to_string(),
                ]
            }
            types::TriggerEvent::LedgerPosted { .. } => {
                vec![
                    "owner".to_string(),
                    "unit".to_string(),
                    "amount".to_string(),
                    "balance".to_string(),
                    "balance_before".to_string(),
                    "entry_sequence".to_string(),
                    "reason".to_string(),
                ]
            }
            types::TriggerEvent::SettingChanged { .. } => {
                vec![
                    "setting".to_string(),
                    "level".to_string(),
                    "subject".to_string(),
                ]
            }
            types::TriggerEvent::ScheduleDue { .. } => {
                vec!["schedule".to_string(), "due_at".to_string()]
            }
            types::TriggerEvent::InboundWebhook { .. } => {
                vec![
                    "endpoint".to_string(),
                    "event_id".to_string(),
                    "body".to_string(),
                ]
            }
        }),
    )
}

/// definitions.rs trigger_problems, one trigger: an unknown automation; for a record event an unknown object type and, with a transition, no workflow of the type with a transition of that name; a condition that does not check as a truth value against the parameters of its event and the fields of its record (truth-problem).
///
/// Specification function `trigger-def-problems`.
pub fn trigger_def_problems(
    schema: &types::TenantSchema,
    roles: &Vec<types::RoleId>,
    t: &types::TriggerDef,
) -> Vec<String> {
    let at = format!("trigger {}", t.id.0);
    let p1 = if automations_of(schema).get(&t.automation).is_none() {
        vec![format!("{at}: unknown automation {}", t.automation.0)]
    } else {
        Vec::<String>::new()
    };
    let p2 = match &t.on {
        types::TriggerEvent::RecordCreated { object } => {
            if schema.objects.get(object).is_none() {
                vec![format!("{at}: unknown object type {}", object.0)]
            } else {
                Vec::<String>::new()
            }
        }
        types::TriggerEvent::RecordUpdated { object, transition } => {
            match schema.objects.get(object) {
                None => vec![format!("{at}: unknown object type {}", object.0)],
                Some(_) => match transition {
                    Some(name) => {
                        if schema.workflows.values().any(|w| {
                            w.object == *object && w.transitions.iter().any(|x| x.name == *name)
                        }) {
                            Vec::<String>::new()
                        } else {
                            vec![format!(
                                "{at}: no workflow of {} has a transition {name}",
                                object.0
                            )]
                        }
                    }
                    None => Vec::<String>::new(),
                },
            }
        }
        types::TriggerEvent::RecordDeleted { object } => {
            if schema.objects.get(object).is_none() {
                vec![format!("{at}: unknown object type {}", object.0)]
            } else {
                Vec::<String>::new()
            }
        }
        _ => Vec::<String>::new(),
    };
    let shapes = match &t.on {
        types::TriggerEvent::RecordCreated { object } => match schema.objects.get(object) {
            Some(o) => field_shapes(&o.fields),
            None => std::collections::BTreeMap::<String, String>::new(),
        },
        types::TriggerEvent::RecordUpdated { object, .. } => match schema.objects.get(object) {
            Some(o) => field_shapes(&o.fields),
            None => std::collections::BTreeMap::<String, String>::new(),
        },
        types::TriggerEvent::RecordDeleted { object } => match schema.objects.get(object) {
            Some(o) => field_shapes(&o.fields),
            None => std::collections::BTreeMap::<String, String>::new(),
        },
        _ => std::collections::BTreeMap::<String, String>::new(),
    };
    let p3 = match &t.condition {
        Some(c) => truth_problem(
            &at,
            &"condition".to_string(),
            c,
            &types::ExprCheckEnv {
                fields: shapes.clone(),
                params: event_params(&t.on),
                roles: roles
                    .clone()
                    .into_iter()
                    .map(|item_| item_.0)
                    .collect::<Vec<_>>(),
            },
        ),
        None => Vec::<String>::new(),
    };
    support::concat(&support::concat(&p1, &p2), &p3)
}

/// definitions.rs trigger_problems (WFL-1520, INT-1522, CT-790): more than one hundred triggers, then the problems of each trigger in id order.
///
/// Specification function `trigger-problems`.
pub fn trigger_problems(schema: &types::TenantSchema, roles: &Vec<types::RoleId>) -> Vec<String> {
    let ts = triggers_of(schema).values().cloned().collect::<Vec<_>>();
    support::concat(
        &(if u64::try_from(ts.len()).unwrap_or(u64::MAX) > 100 {
            vec![format!(
                "limit: {} triggers is more than the maximum of 100",
                u64::try_from(ts.len()).unwrap_or(u64::MAX)
            )]
        } else {
            Vec::<String>::new()
        }),
        &ts.iter().fold(Vec::<String>::new(), |ps, t| {
            support::concat(&ps, &trigger_def_problems(schema, roles, t))
        }),
    )
}

/// definitions.rs step_outputs (automation-step-result, WFL-1523): the outputs of a completed step of a kind.
///
/// Specification function `step-outputs`.
pub fn step_outputs(action: &types::AutomationStep) -> Vec<String> {
    match action {
        types::AutomationStep::CreateRecord { .. } => {
            vec!["record".to_string(), "version".to_string()]
        }
        types::AutomationStep::UpdateRecord { .. } => vec!["version".to_string()],
        types::AutomationStep::DeleteRecord { .. } => Vec::<String>::new(),
        types::AutomationStep::PostLedger { .. } => {
            vec!["entry_sequence".to_string(), "balance".to_string()]
        }
        types::AutomationStep::SendMail { .. } => vec!["message".to_string()],
        types::AutomationStep::CreateNotice { .. } => vec!["item".to_string()],
        types::AutomationStep::CallWebhook { .. } => {
            vec!["delivery".to_string(), "status".to_string()]
        }
        types::AutomationStep::WaitFor { .. } => Vec::<String>::new(),
        types::AutomationStep::WaitUntil { .. } => Vec::<String>::new(),
        types::AutomationStep::Branch { .. } => vec!["taken".to_string()],
        types::AutomationStep::FanOut { .. } => {
            vec!["members".to_string(), "batches".to_string()]
        }
        types::AutomationStep::RequestApproval { .. } => {
            vec!["approved".to_string(), "by".to_string()]
        }
        types::AutomationStep::End => Vec::<String>::new(),
    }
}

/// definitions.rs automation_params (D-6523, D-6535): what the expressions of an automation may read: every parameter an event binds, member, and <step>_<output> for each output of each of its steps.
///
/// Specification function `automation-params`.
pub fn automation_params(a: &types::AutomationDef) -> Vec<String> {
    support::concat(
        &[
            "seq".to_string(),
            "at".to_string(),
            "hop".to_string(),
            "transition".to_string(),
            "person".to_string(),
            "segment".to_string(),
            "reason".to_string(),
            "owner".to_string(),
            "unit".to_string(),
            "amount".to_string(),
            "balance".to_string(),
            "balance_before".to_string(),
            "entry_sequence".to_string(),
            "setting".to_string(),
            "level".to_string(),
            "subject".to_string(),
            "schedule".to_string(),
            "due_at".to_string(),
            "endpoint".to_string(),
            "event_id".to_string(),
            "body".to_string(),
            "member".to_string(),
        ],
        &a.steps
            .keys()
            .fold(Vec::<String>::new(), |acc, n| match a.steps.get(n) {
                Some(s) => support::concat(
                    &acc,
                    &step_outputs(&s.action)
                        .iter()
                        .map(|o| format!("{}_{o}", n.0))
                        .collect::<Vec<_>>(),
                ),
                None => acc.clone(),
            }),
    )
}

/// definitions.rs successors: the steps a step names, in order: then and else of a branch, each of a fan-out, approved and refused of an approval, then its next step, then its compensation.
///
/// Specification function `step-successors`.
pub fn step_successors(s: &types::AutomationStepDef) -> Vec<types::StepName> {
    support::concat(
        &support::concat(
            &(match &s.action {
                types::AutomationStep::Branch {
                    then: yes,
                    r#else: no,
                    ..
                } => {
                    vec![yes.clone(), no.clone()]
                }
                types::AutomationStep::FanOut { each, .. } => vec![each.clone()],
                types::AutomationStep::RequestApproval {
                    approved, refused, ..
                } => {
                    vec![approved.clone(), refused.clone()]
                }
                _ => Vec::<types::StepName>::new(),
            }),
            &(match &s.next {
                Some(n) => vec![n.clone()],
                None => Vec::<types::StepName>::new(),
            }),
        ),
        &(match &s.compensate {
            Some(c) => vec![c.clone()],
            None => Vec::<types::StepName>::new(),
        }),
    )
}

/// definitions.rs reachable: the steps reachable from the start step, following every step a step names (step-successors); as many rounds as the automation has steps reach every one.
///
/// Specification function `reachable-steps`.
pub fn reachable_steps(a: &types::AutomationDef) -> Vec<types::StepName> {
    let start = if a.steps.get(&a.start).is_none() {
        Vec::<types::StepName>::new()
    } else {
        vec![a.start.clone()]
    };
    a.steps.keys().fold(start.clone(), |seen, _| {
        seen.iter()
            .fold(seen.clone(), |acc, m| match a.steps.get(m) {
                Some(s) => step_successors(s).iter().fold(acc.clone(), |acc2, x| {
                    if a.steps.get(x).is_some() && !acc2.iter().any(|y| *y == *x) {
                        support::concat(&acc2, &[x.clone()])
                    } else {
                        acc2.clone()
                    }
                }),
                None => acc.clone(),
            })
    })
}

/// definitions.rs written_problems: the problems of the fields a record step writes: an unknown object type, or per field in id order an unknown field and an expression that does not check (expr-problem).
///
/// Specification function `written-problems`.
pub fn written_problems(
    schema: &types::TenantSchema,
    at: &String,
    object: &types::ObjectTypeId,
    fields: &std::collections::BTreeMap<types::FieldId, types::Expr>,
    env: &types::ExprCheckEnv,
) -> Vec<String> {
    match schema.objects.get(object) {
        None => vec![format!("{at}: unknown object type {}", object.0)],
        Some(d) => fields.keys().fold(Vec::<String>::new(), |ps, f| {
            support::concat(
                &support::concat(
                    &ps,
                    &(if d.fields.get(f).is_none() {
                        vec![format!("{at}: unknown field {}", f.0)]
                    } else {
                        Vec::<String>::new()
                    }),
                ),
                &(match fields.get(f) {
                    Some(x) => expr_problem(at, &format!("{}", f.0), x, env),
                    None => Vec::<String>::new(),
                }),
            )
        }),
    }
}

/// definitions.rs automation_problems, one step: each step it names that the automation does not declare, retry attempts outside 1 to 10, then the problems of its action: record steps (written-problems, then record), the expressions of a posting, a mail, a notice, a webhook body and a wait-until, a branch (record and object type named together, the condition a truth value over the fields of that type), a fan-out batch outside 1 to 100, and an approval policy the schema does not have. The bounds of durations (retry delays, attempt timeouts, waits) are checked by the kernel only: the function language does not compile durations.
///
/// Specification function `automation-step-problems`.
pub fn automation_step_problems(
    schema: &types::TenantSchema,
    a: &types::AutomationDef,
    at: &String,
    s: &types::AutomationStepDef,
    env: &types::ExprCheckEnv,
) -> Vec<String> {
    let p1 = step_successors(s)
        .iter()
        .fold(Vec::<String>::new(), |ps, x| {
            if a.steps.get(x).is_none() {
                support::concat(&ps, &[format!("{at}: unknown step {}", x.0)])
            } else {
                ps.clone()
            }
        });
    let p2 = match &s.retry {
        Some(r) => {
            if r.attempts == 0 || r.attempts > 10 {
                vec![format!("{at}: retry attempts outside 1 to 10")]
            } else {
                Vec::<String>::new()
            }
        }
        None => Vec::<String>::new(),
    };
    let mismatch = vec![format!(
        "{at}: a branch names both an object type and a record, or neither"
    )];
    let p3 = match &s.action {
        types::AutomationStep::CreateRecord { object, fields } => {
            written_problems(schema, at, object, fields, env)
        }
        types::AutomationStep::UpdateRecord {
            object,
            record,
            fields,
        } => support::concat(
            &written_problems(schema, at, object, fields, env),
            &expr_problem(at, &"record".to_string(), record, env),
        ),
        types::AutomationStep::DeleteRecord { object, record } => support::concat(
            &written_problems(
                schema,
                at,
                object,
                &std::collections::BTreeMap::<types::FieldId, types::Expr>::new(),
                env,
            ),
            &expr_problem(at, &"record".to_string(), record, env),
        ),
        types::AutomationStep::PostLedger { owner, amount, .. } => support::concat(
            &expr_problem(at, &"owner".to_string(), owner, env),
            &expr_problem(at, &"amount".to_string(), amount, env),
        ),
        types::AutomationStep::SendMail { to, .. } => expr_problem(at, &"to".to_string(), to, env),
        types::AutomationStep::CreateNotice { to, record, .. } => support::concat(
            &expr_problem(at, &"to".to_string(), to, env),
            &(match record {
                Some(r) => expr_problem(at, &"record".to_string(), r, env),
                None => Vec::<String>::new(),
            }),
        ),
        types::AutomationStep::CallWebhook { body, .. } => {
            body.keys()
                .fold(Vec::<String>::new(), |ps, k| match body.get(k) {
                    Some(x) => {
                        support::concat(&ps, &expr_problem(at, &format!("body {k}"), x, env))
                    }
                    None => ps.clone(),
                })
        }
        types::AutomationStep::WaitFor { .. } => Vec::<String>::new(),
        types::AutomationStep::WaitUntil { at: when } => {
            expr_problem(at, &"at".to_string(), when, env)
        }
        types::AutomationStep::Branch {
            condition,
            object,
            record,
            ..
        } => {
            let shapes = match object {
                Some(o) => match record {
                    Some(_) => match schema.objects.get(o) {
                        Some(d) => field_shapes(&d.fields),
                        None => std::collections::BTreeMap::<String, String>::new(),
                    },
                    None => std::collections::BTreeMap::<String, String>::new(),
                },
                None => std::collections::BTreeMap::<String, String>::new(),
            };
            support::concat(
                &(match object {
                    Some(o) => match record {
                        Some(r) => support::concat(
                            &expr_problem(at, &"record".to_string(), r, env),
                            &(if schema.objects.get(o).is_none() {
                                vec![format!("{at}: unknown object type {}", o.0)]
                            } else {
                                Vec::<String>::new()
                            }),
                        ),
                        None => mismatch.clone(),
                    },
                    None => match record {
                        Some(_) => mismatch.clone(),
                        None => Vec::<String>::new(),
                    },
                }),
                &truth_problem(
                    at,
                    &"condition".to_string(),
                    condition,
                    &types::ExprCheckEnv {
                        fields: shapes.clone(),
                        params: env.params.clone(),
                        roles: env.roles.clone(),
                    },
                ),
            )
        }
        types::AutomationStep::FanOut { batch, .. } => {
            if *batch == 0 || *batch > 100 {
                vec![format!("{at}: a fan-out batch is from 1 to 100")]
            } else {
                Vec::<String>::new()
            }
        }
        types::AutomationStep::RequestApproval { policy, .. } => {
            if schema.policies.get(policy).is_none() {
                vec![format!("{at}: unknown policy {}", policy.0)]
            } else {
                Vec::<String>::new()
            }
        }
        types::AutomationStep::End => Vec::<String>::new(),
    };
    support::concat(&support::concat(&p1, &p2), &p3)
}

/// definitions.rs automation_problems, one automation: an id taken by a field workflow, more than fifty steps, an unknown start step, each run-as role the schema does not declare or that is public, a run key that does not check, the problems of each step in name order (automation-step-problems), and, when the start step exists, each step that cannot be reached from it.
///
/// Specification function `automation-def-problems`.
pub fn automation_def_problems(
    schema: &types::TenantSchema,
    roles: &Vec<types::RoleId>,
    a: &types::AutomationDef,
) -> Vec<String> {
    let at = format!("automation {}", a.id.0);
    let p1 = if schema.workflows.get(&a.id).is_none() {
        Vec::<String>::new()
    } else {
        vec![format!("{at}: the id is taken by a field workflow")]
    };
    let p2 = if u64::try_from(a.steps.keys().cloned().collect::<Vec<_>>().len()).unwrap_or(u64::MAX)
        > 50
    {
        vec![format!(
            "{at}: {} steps is more than the maximum of 50",
            u64::try_from(a.steps.keys().cloned().collect::<Vec<_>>().len()).unwrap_or(u64::MAX)
        )]
    } else {
        Vec::<String>::new()
    };
    let has_start = a.steps.get(&a.start).is_some();
    let p3 = if has_start {
        Vec::<String>::new()
    } else {
        vec![format!("{at}: unknown start step {}", a.start.0)]
    };
    let p4 = a.run_as.roles.iter().fold(Vec::<String>::new(), |ps, r| {
        support::concat(
            &support::concat(
                &ps,
                &(if roles.iter().any(|k| *k == *r) {
                    Vec::<String>::new()
                } else {
                    vec![format!("{at}: unknown role {}", r.0)]
                }),
            ),
            &(if r.0 == "public" {
                vec![format!("{at}: everyone already holds public")]
            } else {
                Vec::<String>::new()
            }),
        )
    });
    let env = types::ExprCheckEnv {
        fields: std::collections::BTreeMap::<String, String>::new(),
        params: automation_params(a),
        roles: roles
            .clone()
            .into_iter()
            .map(|item_| item_.0)
            .collect::<Vec<_>>(),
    };
    let p5 = match &a.run_key {
        Some(k) => expr_problem(&at, &"run key".to_string(), k, &env),
        None => Vec::<String>::new(),
    };
    let p6 = a
        .steps
        .keys()
        .fold(Vec::<String>::new(), |ps, n| match a.steps.get(n) {
            Some(s) => support::concat(
                &ps,
                &automation_step_problems(schema, a, &format!("{at}.{}", n.0), s, &env),
            ),
            None => ps.clone(),
        });
    let reached = reachable_steps(a);
    let p7 = if has_start {
        a.steps.keys().fold(Vec::<String>::new(), |ps, n| {
            if reached.iter().any(|r| *r == *n) {
                ps.clone()
            } else {
                support::concat(
                    &ps,
                    &[format!(
                        "{at}.{}: cannot be reached from the start step",
                        n.0
                    )],
                )
            }
        })
    } else {
        Vec::<String>::new()
    };
    support::concat(
        &support::concat(
            &support::concat(
                &support::concat(&support::concat(&support::concat(&p1, &p2), &p3), &p4),
                &p5,
            ),
            &p6,
        ),
        &p7,
    )
}

/// definitions.rs automation_problems (D-6520 to D-6535, INT-1522, CT-792): the problems of each automation in id order.
///
/// Specification function `automation-problems`.
pub fn automation_problems(
    schema: &types::TenantSchema,
    roles: &Vec<types::RoleId>,
) -> Vec<String> {
    automations_of(schema)
        .values()
        .fold(Vec::<String>::new(), |ps, a| {
            support::concat(&ps, &automation_def_problems(schema, roles, a))
        })
}

/// definitions.rs step_id: the id of a step of a tenant operation.
///
/// Specification function `operation-step-id`.
pub fn operation_step_id(step: &types::TenantOperationStep) -> String {
    match step {
        types::TenantOperationStep::CreateRecord { id, .. } => id.clone(),
        types::TenantOperationStep::UpdateRecord { id, .. } => id.clone(),
        types::TenantOperationStep::DeleteRecord { id, .. } => id.clone(),
        types::TenantOperationStep::PostLedger { id, .. } => id.clone(),
    }
}

/// definitions.rs operation_problems, one step: an id that is not a name, an id equal to an input name, the fields of a record step (written-problems), then its record, or the owner, scope and amount of a posting, that do not check.
///
/// Specification function `operation-step-problems`.
pub fn operation_step_problems(
    schema: &types::TenantSchema,
    at: &String,
    inputs: &Vec<String>,
    step: &types::TenantOperationStep,
    env: &types::ExprCheckEnv,
) -> Vec<String> {
    let id = operation_step_id(step);
    let sat = format!("{at}.{id}");
    let p1 = support::concat(
        &(if is_param_name(&id) {
            Vec::<String>::new()
        } else {
            vec![format!("{at}: step {:?} is not a name", id)]
        }),
        &(if inputs.iter().any(|i| *i == id) {
            vec![format!("{at}: step {id} has the name of an input")]
        } else {
            Vec::<String>::new()
        }),
    );
    support::concat(
        &p1,
        &(match step {
            types::TenantOperationStep::CreateRecord { object, fields, .. } => {
                written_problems(schema, &sat, object, fields, env)
            }
            types::TenantOperationStep::UpdateRecord {
                object,
                record,
                fields,
                ..
            } => support::concat(
                &written_problems(schema, &sat, object, fields, env),
                &expr_problem(&sat, &"record".to_string(), record, env),
            ),
            types::TenantOperationStep::DeleteRecord { object, record, .. } => support::concat(
                &written_problems(
                    schema,
                    &sat,
                    object,
                    &std::collections::BTreeMap::<types::FieldId, types::Expr>::new(),
                    env,
                ),
                &expr_problem(&sat, &"record".to_string(), record, env),
            ),
            types::TenantOperationStep::PostLedger {
                owner,
                scope,
                amount,
                ..
            } => support::concat(
                &support::concat(
                    &(match owner {
                        types::TenantOperationPostingOwner::Principal { principal: who } => {
                            expr_problem(&sat, &"owner".to_string(), who, env)
                        }
                        _ => Vec::<String>::new(),
                    }),
                    &(match scope {
                        Some(x) => expr_problem(&sat, &"scope".to_string(), x, env),
                        None => Vec::<String>::new(),
                    }),
                ),
                &expr_problem(&sat, &"amount".to_string(), amount, env),
            ),
        }),
    )
}

/// definitions.rs operation_problems, one tenant operation (OPR-1549): more than sixteen steps or eight postings, no invoker, unknown invoker roles, per input a name that param cannot read and a reference to an unknown object type, inputs declared twice, an unknown subject object type and a subject input that is not a reference to it, per condition a blank error code and a condition that is not a truth value over the inputs and the subject fields, conditions declared twice, per step its problems (operation-step-problems) with the inputs and the ids of the create steps before it as parameters, and steps declared twice. The bound of two hundred nodes on a condition is checked by the kernel only: counting nodes needs recursion, which the function language does not compile.
///
/// Specification function `operation-def-problems`.
pub fn operation_def_problems(
    schema: &types::TenantSchema,
    roles: &Vec<types::RoleId>,
    op: &types::TenantOperationDef,
) -> Vec<String> {
    let at = format!("operation {}", op.id.0);
    let postings = u64::try_from(
        op.steps
            .iter()
            .filter(|&s| match s {
                types::TenantOperationStep::PostLedger { .. } => true,
                _ => false,
            })
            .cloned()
            .collect::<Vec<_>>()
            .len(),
    )
    .unwrap_or(u64::MAX);
    let p1 = support::concat(
        &support::concat(
            &support::concat(
                &(if u64::try_from(op.steps.len()).unwrap_or(u64::MAX) > 16 {
                    vec![format!(
                        "{at}: {} steps is more than the maximum of 16",
                        u64::try_from(op.steps.len()).unwrap_or(u64::MAX)
                    )]
                } else {
                    Vec::<String>::new()
                }),
                &(if postings > 8 {
                    vec![format!(
                        "{at}: {postings} posting steps is more than the maximum of 8"
                    )]
                } else {
                    Vec::<String>::new()
                }),
            ),
            &(if !op.invokers.signed_in && op.invokers.roles.is_empty() {
                vec![format!("{at}: names no invoker")]
            } else {
                Vec::<String>::new()
            }),
        ),
        &op.invokers
            .roles
            .iter()
            .fold(Vec::<String>::new(), |ps, r| {
                if roles.iter().any(|k| *k == *r) {
                    ps.clone()
                } else {
                    support::concat(&ps, &[format!("{at}: unknown role {}", r.0)])
                }
            }),
    );
    let p2 = support::concat(
        &op.inputs.iter().fold(Vec::<String>::new(), |ps, i| {
            support::concat(
                &support::concat(
                    &ps,
                    &(if is_param_name(&i.name) {
                        Vec::<String>::new()
                    } else {
                        vec![format!("{at}: input {:?} is not a name", i.name)]
                    }),
                ),
                &(match ref_target(&i.ty) {
                    Some(t) => {
                        if schema.objects.get(&t).is_none() {
                            vec![format!(
                                "{at}: input {} refers to unknown object type {}",
                                i.name, t.0
                            )]
                        } else {
                            Vec::<String>::new()
                        }
                    }
                    None => Vec::<String>::new(),
                }),
            )
        }),
        &repeated_names(&op.inputs.iter().map(|i| i.name.clone()).collect::<Vec<_>>())
            .iter()
            .map(|n| format!("{at}: input {n} is declared twice"))
            .collect::<Vec<_>>(),
    );
    let inputs = op
        .inputs
        .iter()
        .filter(|&i| is_param_name(&i.name))
        .cloned()
        .collect::<Vec<_>>()
        .iter()
        .map(|i| i.name.clone())
        .collect::<Vec<_>>();
    let p3 = match &op.subject {
        Some(sub) => support::concat(
            &(if schema.objects.get(&sub.object).is_none() {
                vec![format!(
                    "{at}: unknown subject object type {}",
                    sub.object.0
                )]
            } else {
                Vec::<String>::new()
            }),
            &(if op.inputs.iter().any(|i| {
                i.name == sub.input
                    && (match &i.ty {
                        types::FieldType::Ref { target, .. } => *target == sub.object,
                        _ => false,
                    })
            }) {
                Vec::<String>::new()
            } else {
                vec![format!(
                    "{at}: subject input {} is not a reference to {}",
                    sub.input, sub.object.0
                )]
            }),
        ),
        None => Vec::<String>::new(),
    };
    let shapes = match &op.subject {
        Some(sub) => match schema.objects.get(&sub.object) {
            Some(o) => field_shapes(&o.fields),
            None => std::collections::BTreeMap::<String, String>::new(),
        },
        None => std::collections::BTreeMap::<String, String>::new(),
    };
    let p4 = support::concat(
        &op.conditions.iter().fold(Vec::<String>::new(), |ps, c| {
            support::concat(
                &support::concat(
                    &ps,
                    &(if c.error.as_str().trim().to_string() == "" {
                        vec![format!("{at}: condition {} names no error code", c.id)]
                    } else {
                        Vec::<String>::new()
                    }),
                ),
                &truth_problem(
                    &at,
                    &format!("condition {}", c.id),
                    &c.expr,
                    &types::ExprCheckEnv {
                        fields: shapes.clone(),
                        params: inputs.clone(),
                        roles: roles
                            .clone()
                            .into_iter()
                            .map(|item_| item_.0)
                            .collect::<Vec<_>>(),
                    },
                ),
            )
        }),
        &repeated_names(
            &op.conditions
                .iter()
                .map(|c| c.id.clone())
                .collect::<Vec<_>>(),
        )
        .iter()
        .map(|n| format!("{at}: condition {n} is declared twice"))
        .collect::<Vec<_>>(),
    );
    let scan = op.steps.iter().fold(
        types::OperationScan {
            problems: Vec::<String>::new(),
            params: inputs.clone(),
        },
        |acc, s| types::OperationScan {
            problems: support::concat(
                &acc.problems,
                &operation_step_problems(
                    schema,
                    &at,
                    &inputs,
                    s,
                    &types::ExprCheckEnv {
                        fields: shapes.clone(),
                        params: acc.params.clone(),
                        roles: roles
                            .clone()
                            .into_iter()
                            .map(|item_| item_.0)
                            .collect::<Vec<_>>(),
                    },
                ),
            ),
            params: match s {
                types::TenantOperationStep::CreateRecord { id, .. } => {
                    support::concat(&acc.params, &[id.clone()])
                }
                _ => acc.params.clone(),
            },
        },
    );
    let p5 = support::concat(
        &scan.problems,
        &repeated_names(
            &op.steps
                .iter()
                .map(|s| operation_step_id(s))
                .collect::<Vec<_>>(),
        )
        .iter()
        .map(|n| format!("{at}: step {n} is declared twice"))
        .collect::<Vec<_>>(),
    );
    support::concat(
        &support::concat(&support::concat(&support::concat(&p1, &p2), &p3), &p4),
        &p5,
    )
}

/// definitions.rs operation_problems (D-6546 to D-6549, OPR-1549): the problems of each tenant operation in id order.
///
/// Specification function `operation-problems`.
pub fn operation_problems(schema: &types::TenantSchema, roles: &Vec<types::RoleId>) -> Vec<String> {
    operations_of(schema)
        .values()
        .fold(Vec::<String>::new(), |ps, op| {
            support::concat(&ps, &operation_def_problems(schema, roles, op))
        })
}

/// rules.rs holds_power (D-6547): whether a principal holds an action on a resource without a condition, which is holds-policy-power with no condition: the owner does, a role permission on the object type gives it, and so does a policy of one of its roles that names the action, reaches the resource and has no condition.
///
/// Specification function `holds-power`.
pub fn holds_power(
    tenant: &types::TenantState,
    principal: &types::Principal,
    action: &types::Action,
    resource: &types::Resource,
) -> bool {
    holds_policy_power(tenant, principal, action, resource, &None)
}

/// transition.rs require_operation_powers: what the definer of a tenant operation lacks (D-6547, OPR-1547): each action on an object type a record step uses that it does not hold (holds-power), once, in step order, written <Action> on <Resource>; then capability ledger-post when a step posts and the definer, not an owner, does not hold it.
///
/// Specification function `operation-lacks`.
pub fn operation_lacks(
    tenant: &types::TenantState,
    principal: &types::Principal,
    op: &types::TenantOperationDef,
) -> Vec<String> {
    let actions = op.steps.iter().fold(Vec::<String>::new(), |acc, s| {
        let one = match s {
            types::TenantOperationStep::CreateRecord { object, .. } => {
                if holds_power(
                    tenant,
                    principal,
                    &types::Action::Create,
                    &types::Resource::Object(object.clone()),
                ) {
                    Vec::<String>::new()
                } else {
                    vec![format!(
                        "{} on {}",
                        action_debug(&types::Action::Create),
                        resource_debug(&types::Resource::Object(object.clone()))
                    )]
                }
            }
            types::TenantOperationStep::UpdateRecord { object, .. } => {
                if holds_power(
                    tenant,
                    principal,
                    &types::Action::Update,
                    &types::Resource::Object(object.clone()),
                ) {
                    Vec::<String>::new()
                } else {
                    vec![format!(
                        "{} on {}",
                        action_debug(&types::Action::Update),
                        resource_debug(&types::Resource::Object(object.clone()))
                    )]
                }
            }
            types::TenantOperationStep::DeleteRecord { object, .. } => {
                if holds_power(
                    tenant,
                    principal,
                    &types::Action::Delete,
                    &types::Resource::Object(object.clone()),
                ) {
                    Vec::<String>::new()
                } else {
                    vec![format!(
                        "{} on {}",
                        action_debug(&types::Action::Delete),
                        resource_debug(&types::Resource::Object(object.clone()))
                    )]
                }
            }
            types::TenantOperationStep::PostLedger { .. } => Vec::<String>::new(),
        };
        one.iter().fold(acc.clone(), |acc2, x| {
            if acc2.iter().any(|y| *y == *x) {
                acc2.clone()
            } else {
                support::concat(&acc2, &[x.clone()])
            }
        })
    });
    let posts = op.steps.iter().any(|s| match s {
        types::TenantOperationStep::PostLedger { .. } => true,
        _ => false,
    });
    let holds_post = roles_of(tenant, principal).iter().any(|r| r.0 == "owner")
        || effective_permissions(tenant, principal)
            .iter()
            .any(|g| *g == types::Grant::Capability("ledger-post".to_string()));
    support::concat(
        &actions,
        &(if posts && !holds_post {
            vec!["capability ledger-post".to_string()]
        } else {
            Vec::<String>::new()
        }),
    )
}

/// transition.rs require_capability: the acting principal holds a capability (the owner holds every one); the check permission:capability:<name> is evidence, and a principal without it is refused as Unauthorized.
///
/// Specification function `require-capability`; fails with `rejection`.
pub fn require_capability(
    d: &types::Draft,
    name: &String,
) -> Result<types::Draft, types::Rejection> {
    let rule = format!("permission:capability:{name}");
    let holds = roles_of(&d.tenant, &d.ctx.principal)
        .iter()
        .any(|r| r.0 == "owner")
        || effective_permissions(&d.tenant, &d.ctx.principal)
            .iter()
            .any(|g| *g == types::Grant::Capability(name.clone()));
    Ok(if holds {
        types::Draft {
            tenant: d.tenant.clone(),
            ctx: d.ctx.clone(),
            coverage: d.coverage.clone(),
            ops: d.ops.clone(),
            events: d.events.clone(),
            effects: d.effects.clone(),
            evidence: support::concat(
                &d.evidence,
                &[types::Check {
                    rule: rule.clone(),
                    passed: true,
                    detail: format!("holds {name}"),
                }],
            ),
            next_record: d.next_record,
        }
    } else {
        return Err(draft_reject(
            &support::concat(
                &d.evidence,
                &[types::Check {
                    rule: rule.clone(),
                    passed: false,
                    detail: format!("does not hold {name}"),
                }],
            ),
            &types::ErrorKind::Unauthorized,
            &format!("the change needs the capability {name}"),
        ));
    })
}

/// transition.rs require_operation_powers (D-6547, OPR-1547): the definer of a tenant operation holds every power its steps use (operation-lacks); the check operation:<id>:definer_powers is evidence, and a definer who lacks one is refused as Unauthorized naming what it lacks.
///
/// Specification function `require-operation-powers`; fails with `rejection`.
pub fn require_operation_powers(
    d: &types::Draft,
    op: &types::TenantOperationDef,
) -> Result<types::Draft, types::Rejection> {
    let lacking = operation_lacks(&d.tenant, &d.ctx.principal, op);
    let rule = format!("operation:{}:definer_powers", op.id.0);
    let detail = lacking.iter().fold("".to_string(), |acc, l| {
        if acc == "" {
            l.clone()
        } else {
            format!("{acc}, {l}")
        }
    });
    Ok(if lacking.is_empty() {
        types::Draft {
            tenant: d.tenant.clone(),
            ctx: d.ctx.clone(),
            coverage: d.coverage.clone(),
            ops: d.ops.clone(),
            events: d.events.clone(),
            effects: d.effects.clone(),
            evidence: support::concat(
                &d.evidence,
                &[types::Check {
                    rule: rule.clone(),
                    passed: true,
                    detail: "the definer holds every power the steps use".to_string(),
                }],
            ),
            next_record: d.next_record,
        }
    } else {
        return Err(draft_reject(
            &support::concat(
                &d.evidence,
                &[types::Check {
                    rule: rule.clone(),
                    passed: false,
                    detail: detail.clone(),
                }],
            ),
            &types::ErrorKind::Unauthorized,
            &format!("may not define operation {}: lacks {detail}", op.id.0),
        ));
    })
}

/// transition.rs require_definition_authority: beyond Manage on Schema, a change of a trigger or an automation needs the capability automations-define (WFL-1520), checked once and first; then, in the order of the changes, every run-as role of a defined automation is one the principal may confer (require-conferrable, ADM-152, WFL-1528) and the definer of a tenant operation holds every power its steps use (require-operation-powers).
///
/// Specification function `require-definition-authority`; fails with `rejection` (`Failure::Error`), and an integer overflow, a division by zero or a failed conversion is `Failure::Fault`.
pub fn require_definition_authority(
    d: &types::Draft,
    changes: &Vec<types::SchemaChange>,
) -> Result<types::Draft, Failure<types::Rejection>> {
    let automation = changes.iter().any(|c| match c {
        types::SchemaChange::DefineTrigger(_) => true,
        types::SchemaChange::RemoveTrigger(_) => true,
        types::SchemaChange::DefineAutomation(_) => true,
        types::SchemaChange::RemoveAutomation(_) => true,
        _ => false,
    });
    let d1 = if automation {
        require_capability(d, &"automations-define".to_string()).map_err(Failure::Error)?
    } else {
        d.clone()
    };
    Ok({
        let mut acc: types::Draft = d1.clone();
        for c in changes.iter() {
            acc = match c {
                types::SchemaChange::DefineAutomation(a) => require_conferrable(
                    &acc,
                    &a.run_as.roles.iter().map(|r| r.clone()).collect::<Vec<_>>(),
                )?,
                types::SchemaChange::DefineOperation(op) => {
                    require_operation_powers(&acc, op).map_err(Failure::Error)?
                }
                _ => acc.clone(),
            };
        }
        acc
    })
}

/// The mail templates of a schema by id, none when it holds no table of them (TenantSchema.mail_templates, an optional map).
