    /// authors_own_posts covers an author updating a post.
    #[test]
    fn policy_applies_example_1() {
        let policy: types::PolicyDef = types::PolicyDef {
            id: types::PolicyId("authors_own_posts".to_string()),
            role: types::RoleId("author".to_string()),
            resource: types::Resource::Object(types::ObjectTypeId("post".to_string())),
            actions: std::collections::BTreeSet::from([
                types::Action::Read,
                types::Action::Update,
                types::Action::Delete,
            ]),
            condition: Some(types::Expr::Cmp(
                types::CmpOp::Eq,
                Box::new(types::Expr::Var(
                    types::Scope::Record,
                    "$created_by".to_string(),
                )),
                Box::new(types::Expr::Principal),
            )),
        };
        let roles: std::collections::BTreeSet<types::RoleId> = std::collections::BTreeSet::from([
            types::RoleId("author".to_string()),
            types::RoleId("public".to_string()),
        ]);
        let action: types::Action = types::Action::Update;
        let resource: types::Resource =
            types::Resource::Object(types::ObjectTypeId("post".to_string()));
        assert!(policy_applies(&policy, &roles, &action, &resource));
    }

