    /// Example 1 of `record-scope`.
    #[test]
    fn record_scope_example_1() {
        let r: types::Record = types::Record {
            id: types::RecordId(1),
            object: types::ObjectTypeId("note".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
            created_at: crate::prelude::Timestamp(5000),
            updated_at: crate::prelude::Timestamp(5000),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("slug".to_string()),
                    types::Value::Str("first".to_string()),
                ),
                (
                    types::FieldId("status".to_string()),
                    types::Value::Str("draft".to_string()),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("First".to_string()),
                ),
            ]),
        };
        let want_: std::collections::BTreeMap<String, types::Value> =
            std::collections::BTreeMap::from([
                ("$created_at".to_string(), types::Value::Time(5000)),
                (
                    "$created_by".to_string(),
                    types::Value::Str("alpha:writer1".to_string()),
                ),
                ("$id".to_string(), types::Value::Ref(types::RecordId(1))),
                ("$updated_at".to_string(), types::Value::Time(5000)),
                ("$version".to_string(), types::Value::Int(1)),
                ("slug".to_string(), types::Value::Str("first".to_string())),
                ("status".to_string(), types::Value::Str("draft".to_string())),
                ("title".to_string(), types::Value::Str("First".to_string())),
            ]);
        assert_eq!(record_scope(&r), Ok(want_));
    }

