    /// An evaluation error rejects the intent (the text after the colon is the evaluator's own wording, not the kernel's).
    #[test]
    fn defaults_example_4() {
        let object: types::ObjectTypeDef = types::ObjectTypeDef {
            id: types::ObjectTypeId("note".to_string()),
            label: "Note".to_string(),
            fields: std::collections::BTreeMap::from([(
                types::FieldId("bad".to_string()),
                types::FieldDef {
                    id: types::FieldId("bad".to_string()),
                    label: "Bad".to_string(),
                    ty: types::FieldType::Bool,
                    required: false,
                    unique: false,
                    default: Some(types::Expr::Cmp(
                        types::CmpOp::Eq,
                        Box::new(types::Expr::Lit(types::Value::Str("a".to_string()))),
                        Box::new(types::Expr::Lit(types::Value::Int(1))),
                    )),
                    read: None,
                    personal: None,
                },
            )]),
            constraints: std::collections::BTreeMap::new(),
            retention: None,
            publication: None,
            language_field: None,
            translation_group: None,
            unique: None,
        };
        let fields: std::collections::BTreeMap<types::FieldId, types::Value> =
            std::collections::BTreeMap::new();
        let principal: types::Principal =
            types::Principal::User(types::PrincipalId("alpha:writer1".to_string()));
        let now: crate::prelude::Timestamp = crate::prelude::Timestamp(5000);
        let tenant: types::TenantState = types::TenantState {
            id: types::TenantId("alpha".to_string()),
            name: "alpha".to_string(),
            revision: types::StateRevision(10),
            next_record: 2,
            event_seq: 10,
            schema: std::sync::Arc::new(types::TenantSchema {
                version: types::SchemaVersion(1),
                objects: std::collections::BTreeMap::new(),
                roles: std::collections::BTreeMap::from([
                    (
                        types::RoleId("owner".to_string()),
                        types::RoleDef {
                            id: types::RoleId("owner".to_string()),
                            label: "Owner".to_string(),
                        },
                    ),
                    (
                        types::RoleId("public".to_string()),
                        types::RoleDef {
                            id: types::RoleId("public".to_string()),
                            label: "Everyone".to_string(),
                        },
                    ),
                ]),
                role_permissions: None,
                teams: None,
                invitations: None,
                policies: std::collections::BTreeMap::new(),
                workflows: std::collections::BTreeMap::new(),
                queries: std::collections::BTreeMap::new(),
                views: std::collections::BTreeMap::new(),
                triggers: None,
                automations: None,
                operations: None,
                settings: None,
                capabilities: None,
                ledger: None,
                mail_templates: None,
                notice_templates: None,
                tokens: None,
                products: None,
            }),
            members: std::collections::BTreeMap::from([(
                types::PrincipalId("alpha:writer1".to_string()),
                std::collections::BTreeSet::from([types::RoleId("writer".to_string())]),
            )]),
            records: std::collections::BTreeMap::new(),
            setting_values: None,
            ledger: None,
        };
        let evidence: Vec<types::Check> = vec![types::Check {
            rule: "intent:shape".to_string(),
            passed: true,
            detail: "ok".to_string(),
        }];
        let texts: std::collections::BTreeMap<types::FieldId, String> =
            std::collections::BTreeMap::from([(
                types::FieldId("bad".to_string()),
                "('a' == 1)".to_string(),
            )]);
        assert_eq!(
            defaults(&object, &fields, &principal, now, &tenant, &evidence, &texts),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::Evaluation,
                message: "default of bad: cannot compare a string with a int".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "intent:shape".to_string(),
                        passed: true,
                        detail: "ok".to_string()
                    },
                    types::Check {
                        rule: "intent:evaluation".to_string(),
                        passed: false,
                        detail: "default of bad: cannot compare a string with a int".to_string()
                    }
                ],
                missing: None
            }))
        );
    }

