    /// Example 1 of `json-number-text`.
    #[test]
    fn json_number_text_example_1() {
        let n: types::JsonNumber = types::JsonNumber::PosInt(3);
        let want_: String = "3".to_string();
        assert_eq!(json_number_text(&n), want_);
    }

    /// Example 2 of `json-number-text`.
    #[test]
    fn json_number_text_example_2() {
        let n: types::JsonNumber = types::JsonNumber::NegInt(-3);
        let want_: String = "-3".to_string();
        assert_eq!(json_number_text(&n), want_);
    }

    /// Example 3 of `json-number-text`.
    #[test]
    fn json_number_text_example_3() {
        let n: types::JsonNumber = types::JsonNumber::Float(1.5);
        let want_: String = "1.5".to_string();
        assert_eq!(json_number_text(&n), want_);
    }

