    /// Example 1 of `coerce-mismatch`.
    #[test]
    fn coerce_mismatch_example_1() {
        let ty: types::FieldType = types::FieldType::Int;
        let j: types::PlainJson = types::PlainJson::String("3".to_string());
        let want_: types::PlainError =
            types::PlainError::Message("expected int, got \"3\"".to_string());
        assert_eq!(coerce_mismatch(&ty, &j), want_);
    }

    /// plain.rs coerces_by_field_type: null stays null.
    #[test]
    fn coerce_scalar_example_1() {
        let ty: types::FieldType = types::FieldType::Bool;
        let j: types::PlainJson = types::PlainJson::Null;
        let refs: std::collections::BTreeMap<String, types::RecordId> =
            std::collections::BTreeMap::new();
        let times: std::collections::BTreeMap<String, i64> = std::collections::BTreeMap::new();
        let want_: types::Value = types::Value::Null;
        assert_eq!(coerce_scalar(&ty, &j, &refs, &times), Ok(want_));
    }

    /// plain.rs coerces_by_field_type: a string is not an int.
    #[test]
    fn coerce_scalar_example_2() {
        let ty: types::FieldType = types::FieldType::Int;
        let j: types::PlainJson = types::PlainJson::String("3".to_string());
        let refs: std::collections::BTreeMap<String, types::RecordId> =
            std::collections::BTreeMap::new();
        let times: std::collections::BTreeMap<String, i64> = std::collections::BTreeMap::new();
        assert_eq!(
            coerce_scalar(&ty, &j, &refs, &times),
            Err(Failure::Error(types::PlainError::Message(
                "expected int, got \"3\"".to_string()
            )))
        );
    }

    /// plain.rs coerces_by_field_type: a UTC date.
    #[test]
    fn coerce_scalar_example_3() {
        let ty: types::FieldType = types::FieldType::Time;
        let j: types::PlainJson = types::PlainJson::String("1970-01-02".to_string());
        let refs: std::collections::BTreeMap<String, types::RecordId> =
            std::collections::BTreeMap::new();
        let times: std::collections::BTreeMap<String, i64> =
            std::collections::BTreeMap::from([("1970-01-02".to_string(), 86400000)]);
        let want_: types::Value = types::Value::Time(86400000);
        assert_eq!(coerce_scalar(&ty, &j, &refs, &times), Ok(want_));
    }

    /// plain.rs parses_utc_timestamps: a time needs its Z.
    #[test]
    fn coerce_scalar_example_4() {
        let ty: types::FieldType = types::FieldType::Time;
        let j: types::PlainJson = types::PlainJson::String("2026-11-18T09:30".to_string());
        let refs: std::collections::BTreeMap<String, types::RecordId> =
            std::collections::BTreeMap::new();
        let times: std::collections::BTreeMap<String, i64> = std::collections::BTreeMap::new();
        assert_eq!(
            coerce_scalar(&ty, &j, &refs, &times),
            Err(Failure::Error(types::PlainError::Message(
                "not a UTC timestamp: \"2026-11-18T09:30\"".to_string()
            )))
        );
    }

    /// Example 5 of `coerce-scalar`.
    #[test]
