    /// behaviour.rs only_the_system_creates_tenants_and_a_tenant_is_created_once.
    #[test]
    fn create_tenant_example_1() {
        let c: types::Context = types::Context {
            tenant: types::TenantId("gamma".to_string()),
            principal: types::Principal::System,
            session: None,
            now: crate::prelude::Timestamp(5001),
            correlation: "test-5001".to_string(),
            verified_address: None,
            idempotency_key: None,
            language: None,
            hop: None,
        };
        let name: String = "Gamma".to_string();
        let owner: types::PrincipalId = types::PrincipalId("gamma:owner".to_string());
        let blank: bool = false;
        let want_: types::TransitionResult = types::TransitionResult {
            delta: types::StateDelta {
                tenant: types::TenantId("gamma".to_string()),
                base_revision: None,
                new_revision: types::StateRevision(1),
                next_record: 1,
                event_seq: 1,
                ops: vec![
                    types::DeltaOp::CreateTenant {
                        name: "Gamma".to_string(),
                    },
                    types::DeltaOp::PutSchema(std::sync::Arc::new(types::TenantSchema {
                        version: types::SchemaVersion(1),
                        objects: std::collections::BTreeMap::new(),
                        roles: std::collections::BTreeMap::from([
                            (
                                types::RoleId("owner".to_string()),
                                types::RoleDef {
                                    id: types::RoleId("owner".to_string()),
                                    label: "Owner".to_string(),
                                },
                            ),
                            (
                                types::RoleId("public".to_string()),
                                types::RoleDef {
                                    id: types::RoleId("public".to_string()),
                                    label: "Everyone".to_string(),
                                },
                            ),
                        ]),
                        role_permissions: None,
                        teams: None,
                        invitations: None,
                        policies: std::collections::BTreeMap::new(),
                        workflows: std::collections::BTreeMap::new(),
                        queries: std::collections::BTreeMap::new(),
                        views: std::collections::BTreeMap::new(),
                        triggers: None,
                        automations: None,
                        operations: None,
                        settings: None,
                        capabilities: None,
                        ledger: None,
                        mail_templates: None,
                        notice_templates: None,
                        tokens: None,
                        products: None,
                    })),
                    types::DeltaOp::PutMember {
                        principal: types::PrincipalId("gamma:owner".to_string()),
                        roles: std::collections::BTreeSet::from([types::RoleId(
                            "owner".to_string(),
                        )]),
                    },
                ],
            },
            events: vec![types::DomainEvent {
                tenant: types::TenantId("gamma".to_string()),
                seq: 1,
                revision: types::StateRevision(1),
                at: crate::prelude::Timestamp(5001),
                principal: types::Principal::System,
                correlation: "test-5001".to_string(),
                body: types::EventBody::TenantCreated {
                    name: "Gamma".to_string(),
                },
            }],
            effects: vec![types::Effect::Publish { seq: 1 }],
            evidence: vec![types::Check {
                rule: "policy:builtin_system".to_string(),
                passed: true,
                detail: "CreateTenant".to_string(),
            }],
            output: types::Output::Tenant,
        };
        assert_eq!(create_tenant(&c, &name, &owner, blank), Ok(want_));
    }

    /// behaviour.rs only_the_system_creates_tenants_and_a_tenant_is_created_once: refused to a user, the owner of another tenant.
    #[test]
    fn create_tenant_example_2() {
        let c: types::Context = types::Context {
            tenant: types::TenantId("gamma".to_string()),
            principal: types::Principal::User(types::PrincipalId("alpha:owner".to_string())),
            session: None,
            now: crate::prelude::Timestamp(1),
            correlation: "test-1".to_string(),
            verified_address: None,
            idempotency_key: None,
            language: None,
            hop: None,
        };
        let name: String = "Gamma".to_string();
        let owner: types::PrincipalId = types::PrincipalId("gamma:owner".to_string());
        let blank: bool = false;
        assert_eq!(
            create_tenant(&c, &name, &owner, blank),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::Unauthorized,
                message: "only the system creates tenants".to_string(),
                evidence: vec![types::Check {
                    rule: "policy:builtin_system".to_string(),
                    passed: false,
                    detail: "CreateTenant".to_string()
                }],
                missing: None
            }))
        );
    }

    /// behaviour.rs every_rejection_lists_at_least_one_failed_check: tenant without a name (" ").
    #[test]
    fn create_tenant_example_3() {
        let c: types::Context = types::Context {
            tenant: types::TenantId("gamma".to_string()),
            principal: types::Principal::System,
            session: None,
            now: crate::prelude::Timestamp(5001),
            correlation: "test-5001".to_string(),
            verified_address: None,
            idempotency_key: None,
            language: None,
            hop: None,
        };
        let name: String = " ".to_string();
        let owner: types::PrincipalId = types::PrincipalId("gamma:owner".to_string());
        let blank: bool = true;
        assert_eq!(
            create_tenant(&c, &name, &owner, blank),
            Err(types::Rejection::Rejected(types::DomainError {
                kind: types::ErrorKind::InvalidIntent,
                message: "a tenant needs a name".to_string(),
                evidence: vec![types::Check {
                    rule: "intent:tenant_has_name".to_string(),
                    passed: false,
                    detail: "a tenant needs a name".to_string()
                }],
                missing: None
            }))
        );
    }

