    /// Example 3 of `coerce-mutation`.
    #[test]
    fn coerce_mutation_example_3() {
        let mutation: types::Mutation = types::Mutation::Create {
            object: "post".to_string(),
            fields: std::collections::BTreeMap::new(),
        };
        let state: types::State = types::State {
            tenant_id: types::TenantId("alpha".to_string()),
            tenant: None,
            coverage: types::Coverage::Complete,
        };
        let context: types::Context = types::Context {
            tenant: types::TenantId("alpha".to_string()),
            principal: types::Principal::User(types::PrincipalId("alpha:owner".to_string())),
            session: Some(types::SessionId("s-1".to_string())),
            now: crate::prelude::Timestamp(3000),
            correlation: "c-1".to_string(),
            verified_address: None,
            idempotency_key: None,
            language: None,
            hop: None,
        };
        let times: std::collections::BTreeMap<String, i64> = std::collections::BTreeMap::new();
        assert_eq!(
            coerce_mutation(&mutation, &state, &context, &times),
            Err(Failure::Error(types::ApiFailure::Refused(
                types::ApiError {
                    code: types::ErrorCode::NotFound,
                    message: "no site alpha".to_string(),
                    kind: None,
                    failed: Some(Vec::new()),
                    correlation: "c-1".to_string()
                }
            )))
        );
    }

