    /// A row with an included author and a markdown field.
    #[test]
    fn project_row_example_1() {
        let r: types::Record = types::Record {
            id: types::RecordId(2),
            object: types::ObjectTypeId("post".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:writer".to_string())),
            created_at: crate::prelude::Timestamp(2000),
            updated_at: crate::prelude::Timestamp(2000),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("author".to_string()),
                    types::Value::Ref(types::RecordId(1)),
                ),
                (
                    types::FieldId("status".to_string()),
                    types::Value::Str("published".to_string()),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("B".to_string()),
                ),
            ]),
        };
        let section: types::SectionData = types::SectionData {
            single: false,
            rows: vec![types::Record {
                id: types::RecordId(2),
                object: types::ObjectTypeId("post".to_string()),
                version: 1,
                created_by: Some(types::PrincipalId("alpha:writer".to_string())),
                created_at: crate::prelude::Timestamp(2000),
                updated_at: crate::prelude::Timestamp(2000),
                fields: std::collections::BTreeMap::from([
                    (
                        types::FieldId("author".to_string()),
                        types::Value::Ref(types::RecordId(1)),
                    ),
                    (
                        types::FieldId("status".to_string()),
                        types::Value::Str("published".to_string()),
                    ),
                    (
                        types::FieldId("title".to_string()),
                        types::Value::Str("B".to_string()),
                    ),
                ]),
            }],
            included: std::collections::BTreeMap::from([(
                types::FieldId("author".to_string()),
                std::collections::BTreeMap::from([(
                    types::RecordId(1),
                    types::Record {
                        id: types::RecordId(1),
                        object: types::ObjectTypeId("person".to_string()),
                        version: 1,
                        created_by: None,
                        created_at: crate::prelude::Timestamp(1000),
                        updated_at: crate::prelude::Timestamp(1000),
                        fields: std::collections::BTreeMap::from([(
                            types::FieldId("name".to_string()),
                            types::Value::Str("Ada".to_string()),
                        )]),
                    },
                )]),
            )]),
            markdown: vec![types::FieldId("title".to_string())],
            aggregate: None,
        };
        let markdown: std::collections::BTreeMap<String, types::MarkdownSummary> =
            std::collections::BTreeMap::from([(
                "B".to_string(),
                types::MarkdownSummary {
                    blocks: types::PlainJson::Array(Vec::new()),
                    words: 1,
                },
            )]);
        let none: types::PlainJson = types::PlainJson::Null;
        let want_: types::PlainJson = types::PlainJson::Object(std::collections::BTreeMap::from([
            (
                "blocks".to_string(),
                types::PlainJson::Object(std::collections::BTreeMap::from([(
                    "title".to_string(),
                    types::PlainJson::Array(Vec::new()),
                )])),
            ),
            (
                "created_at".to_string(),
                types::PlainJson::Number(types::JsonNumber::PosInt(2000)),
            ),
            (
                "created_by".to_string(),
                types::PlainJson::String("alpha:writer".to_string()),
            ),
            (
                "fields".to_string(),
                types::PlainJson::Object(std::collections::BTreeMap::from([
                    (
                        "author".to_string(),
                        types::PlainJson::Number(types::JsonNumber::PosInt(1)),
                    ),
                    (
                        "status".to_string(),
                        types::PlainJson::String("published".to_string()),
                    ),
                    (
                        "title".to_string(),
                        types::PlainJson::String("B".to_string()),
                    ),
                ])),
            ),
            (
                "id".to_string(),
                types::PlainJson::Number(types::JsonNumber::PosInt(2)),
            ),
            (
                "object".to_string(),
                types::PlainJson::String("post".to_string()),
            ),
            (
                "reading_minutes".to_string(),
                types::PlainJson::Number(types::JsonNumber::PosInt(1)),
            ),
            (
                "refs".to_string(),
                types::PlainJson::Object(std::collections::BTreeMap::from([(
                    "author".to_string(),
                    types::PlainJson::Object(std::collections::BTreeMap::from([
                        (
                            "created_at".to_string(),
                            types::PlainJson::Number(types::JsonNumber::PosInt(1000)),
                        ),
                        ("created_by".to_string(), types::PlainJson::Null),
                        (
                            "fields".to_string(),
                            types::PlainJson::Object(std::collections::BTreeMap::from([(
                                "name".to_string(),
                                types::PlainJson::String("Ada".to_string()),
                            )])),
                        ),
                        (
                            "id".to_string(),
                            types::PlainJson::Number(types::JsonNumber::PosInt(1)),
                        ),
                        (
                            "object".to_string(),
                            types::PlainJson::String("person".to_string()),
                        ),
                        (
                            "updated_at".to_string(),
                            types::PlainJson::Number(types::JsonNumber::PosInt(1000)),
                        ),
                        (
                            "version".to_string(),
                            types::PlainJson::Number(types::JsonNumber::PosInt(1)),
                        ),
                    ])),
                )])),
            ),
            (
                "updated_at".to_string(),
                types::PlainJson::Number(types::JsonNumber::PosInt(2000)),
            ),
            (
                "version".to_string(),
                types::PlainJson::Number(types::JsonNumber::PosInt(1)),
            ),
        ]));
        assert_eq!(project_row(&r, &section, &markdown, &none), Ok(want_));
    }

    /// A single section without a row is null.
    #[test]
    fn project_view_example_1() {
        let data: types::ViewData = types::ViewData {
            view: types::ViewId("one".to_string()),
            title: "Post".to_string(),
            params: std::collections::BTreeMap::from([("title".to_string(), "Q".to_string())]),
            sections: std::collections::BTreeMap::from([(
                "post".to_string(),
                types::SectionData {
                    single: true,
                    rows: Vec::new(),
                    included: std::collections::BTreeMap::new(),
                    markdown: Vec::new(),
                    aggregate: None,
                },
            )]),
            depends_on: std::collections::BTreeSet::from([types::ObjectTypeId("post".to_string())]),
            revision: types::StateRevision(5),
            schema_version: types::SchemaVersion(2),
        };
        let markdown: std::collections::BTreeMap<String, types::MarkdownSummary> =
            std::collections::BTreeMap::new();
        let none: types::PlainJson = types::PlainJson::Null;
        let want_: types::PlainJson = types::PlainJson::Object(std::collections::BTreeMap::from([
            (
                "data".to_string(),
                types::PlainJson::Object(std::collections::BTreeMap::from([(
                    "post".to_string(),
                    types::PlainJson::Null,
                )])),
            ),
            (
                "depends_on".to_string(),
                types::PlainJson::Array(vec![types::PlainJson::String("post".to_string())]),
            ),
            (
                "params".to_string(),
                types::PlainJson::Object(std::collections::BTreeMap::from([(
                    "title".to_string(),
                    types::PlainJson::String("Q".to_string()),
                )])),
            ),
            (
                "revision".to_string(),
                types::PlainJson::Number(types::JsonNumber::PosInt(5)),
            ),
            (
                "schema_version".to_string(),
                types::PlainJson::Number(types::JsonNumber::PosInt(2)),
            ),
            (
                "title".to_string(),
                types::PlainJson::String("Post".to_string()),
            ),
            (
                "view".to_string(),
                types::PlainJson::String("one".to_string()),
            ),
        ]));
        assert_eq!(project_view(&data, &markdown, &none), Ok(want_));
    }

