    /// The grant of the object type and the verb.
    #[test]
    fn grant_allows_example_1() {
        let g: types::Grant = types::Grant::Object(
            types::ObjectTypeId("note".to_string()),
            types::ObjectAction::Update,
        );
        let act: types::Action = types::Action::Update;
        let res: types::Resource = types::Resource::Object(types::ObjectTypeId("note".to_string()));
        assert!(grant_allows(&g, &act, &res));
    }

    /// Another verb is not it.
    #[test]
    fn grant_allows_example_2() {
        let g: types::Grant = types::Grant::Object(
            types::ObjectTypeId("note".to_string()),
            types::ObjectAction::Read,
        );
        let act: types::Action = types::Action::Update;
        let res: types::Resource = types::Resource::Object(types::ObjectTypeId("note".to_string()));
        assert!(!grant_allows(&g, &act, &res));
    }

    /// A capability grants no object action.
    #[test]
    fn grant_allows_example_3() {
        let g: types::Grant = types::Grant::Capability("content-write".to_string());
        let act: types::Action = types::Action::Read;
        let res: types::Resource = types::Resource::Object(types::ObjectTypeId("note".to_string()));
        assert!(!grant_allows(&g, &act, &res));
    }

