    /// Example 1 of `event-params`.
    #[test]
    fn event_params_example_1() {
        let event: types::TriggerEvent = types::TriggerEvent::RecordCreated {
            object: types::ObjectTypeId("note".to_string()),
        };
        let want_: Vec<String> = vec!["seq".to_string(), "at".to_string(), "hop".to_string()];
        assert_eq!(event_params(&event), want_);
    }

    /// Example 2 of `event-params`.
    #[test]
    fn event_params_example_2() {
        let event: types::TriggerEvent = types::TriggerEvent::LedgerPosted {
            unit: types::LedgerUnit("points".to_string()),
        };
        let want_: Vec<String> = vec![
            "seq".to_string(),
            "at".to_string(),
            "hop".to_string(),
            "owner".to_string(),
            "unit".to_string(),
            "amount".to_string(),
            "balance".to_string(),
            "balance_before".to_string(),
            "entry_sequence".to_string(),
            "reason".to_string(),
        ];
        assert_eq!(event_params(&event), want_);
    }

    /// Example 3 of `event-params`.
    #[test]
    fn event_params_example_3() {
        let event: types::TriggerEvent = types::TriggerEvent::InboundWebhook {
            endpoint: "shop".to_string(),
        };
        let want_: Vec<String> = vec![
            "seq".to_string(),
            "at".to_string(),
            "hop".to_string(),
            "endpoint".to_string(),
            "event_id".to_string(),
            "body".to_string(),
        ];
        assert_eq!(event_params(&event), want_);
    }

