    /// Example 1 of `limit-count-problem`.
    #[test]
    fn limit_count_problem_example_1() {
        let what: String = "policies".to_string();
        let count: u64 = 3;
        let max: u64 = 2;
        let want_: Vec<String> =
            vec!["limit: 3 policies is more than the maximum of 2".to_string()];
        assert_eq!(limit_count_problem(&what, count, max), want_);
    }

